/// <summary>
/// CB166_SalesOrderSubstitutes
/// Represents the ordered list of enumeration values for <c>TableGroupAll</c> enum.
/// Allows to add values to the list to support extension.
/// </summary>
public class METSubstituteSiteCodeTypeOrderedList implements Enumerable
{
    List substituteSiteCodeTypeOrderedList;

}

