/// <summary>
/// Get the enumerator of the ordered list.
/// </summary>
/// <returns>An instance of <c>ListEnumerator</c> class.</returns>
public Enumerator getEnumerator()
{
    return substituteSiteCodeTypeOrderedList.getEnumerator();
}

    /// <summary>
    /// New method
    /// </summary>
    protected void new()
    {
        substituteSiteCodeTypeOrderedList = new List(Types::Enum);

        this.initializeSubstituteSiteCodeTypeOrderedList();
    }

/// <summary>
/// Set list in ascending or descending order
/// </summary>
/// <param name = "_enumerateInOrder">Ascending or descending order</param>
private void setEnumerateInOrder(SortOrder _enumerateInOrder)
{
    if (_enumerateInOrder == SortOrder::Descending)
    {
        this.reverseOrderedList();
    }
}

    /// <summary>
    /// Reverse the ordered list
    /// </summary>
    private void reverseOrderedList()
    {
        List reversedSubstituteSiteCodeTypeOrderedList = new List(Types::Enum);
        ListEnumerator enumerator = this.getEnumerator() as ListEnumerator;
        
        while (enumerator.moveNext())
        {
            reversedSubstituteSiteCodeTypeOrderedList.addStart(enumerator.current());
        }

        substituteSiteCodeTypeOrderedList = reversedSubstituteSiteCodeTypeOrderedList;
    }

/// <summary>
/// Constructs a new instance of the <c>METSubstituteSiteCodeTypeOrderedList</c> class to be enumerated in the specified order.
/// </summary>
/// <param name="_enumerateInOrder">Enumerate the values in the enum in the specified order.</param>
/// <returns>An instance of <c>METSubstituteSiteCodeTypeOrderedList</c> class.</returns>
public static METSubstituteSiteCodeTypeOrderedList newFromOrder(SortOrder _enumerateInOrder = SortOrder::Ascending)
{
    METSubstituteSiteCodeTypeOrderedList orderedList = new METSubstituteSiteCodeTypeOrderedList();
    orderedList.setEnumerateInOrder(_enumerateInOrder);
    return orderedList;
}

/// <summary>
/// Initialize the list with all the applicable values of <c>TableGroupAll</c> enumeration in ascending order.
/// </summary>
protected void initializeSubstituteSiteCodeTypeOrderedList()
{
    substituteSiteCodeTypeOrderedList.addEnd(TableGroupAll::Table);
    substituteSiteCodeTypeOrderedList.addEnd(TableGroupAll::All);
}
